INSERT INTO `pages` (`id`, `page_title`, `page_title_ja`, `page_slug`, `page_desc`, `page_desc_ja`, `page_meta`, `page_keywords`) VALUES
(1, 'Refund Policy', '返金ポリシー', 'refund-policy', '<h2>Refund Policy</h2>\r\n<p>This Refund &amp; Cancellation Policy explains, in plain language, when a refund may be available for purchases made on [Company Name]. Our products are digital: you buy credits, and you use those credits to unlock online courses.</p>\r\n\r\n<h3>Digital Products</h3>\r\n<p>Because credits and courses are delivered digitally and give immediate access, purchases are generally final. Please review your order carefully before you buy.</p>\r\n\r\n<h3>Refunds Are for Purchased Credits Only</h3>\r\n<p>Where a refund is granted, please note the following clearly:</p>\r\n<ul>\r\n  <li>Any eligible refund covers <strong>purchased credits only</strong> &mdash; that is, credits you paid for</li>\r\n  <li><strong>All bonus credits are non-refundable.</strong> Bonus credits are a free promotional benefit and are never included in a refund. If bonus credits were added with a top-up, they will be removed as part of any refund or reversal</li>\r\n  <li>Credits that have already been <strong>spent</strong> to unlock a course are non-refundable</li>\r\n</ul>\r\n\r\n<h3>When You May Be Eligible</h3>\r\n<p>You may be eligible for a refund of purchased credits if:</p>\r\n<ul>\r\n  <li>you were charged in error, or charged more than once for the same purchase; or</li>\r\n  <li>a genuine technical problem on our side prevented your credits from being added, and we are unable to fix it; and</li>\r\n  <li>the credits you are asking to refund are <strong>unused</strong> and you make the request within a reasonable time of purchase</li>\r\n</ul>\r\n\r\n<h3>What Is Not Refundable</h3>\r\n<ul>\r\n  <li>Bonus credits of any kind</li>\r\n  <li>Credits already used to unlock a course</li>\r\n  <li>Courses that have already been accessed or viewed</li>\r\n  <li>Purchases where the request is made after an unreasonable period</li>\r\n</ul>\r\n\r\n<h3>How to Request a Refund</h3>\r\n<p>To ask for a refund, email us at <a href=\"mailto:[Company Email]\">enquiry@websitename.com</a> from the address on your account, and include your order number and the reason for your request. We may ask for a little more information to verify the purchase.</p>\r\n\r\n<h3>Processing</h3>\r\n<p>If your request is approved, the refund will be issued to your original payment method. It may take a number of business days to appear, depending on your bank or card provider. The refund amount reflects <strong>purchased credits only</strong>, with any bonus credits excluded.</p>\r\n\r\n<h3>Chargebacks</h3>\r\n<p>If you do not recognise a charge, please contact us before raising a dispute with your bank &mdash; we can usually resolve things faster. Remember that charges appear on your statement under our registered business name (DBA).</p>\r\n\r\n<h3>Contact Us</h3>\r\n<ul>\r\n  <li><strong>[Company Name]</strong></li>\r\n  <li>Email: <a href=\"mailto:[Company Email]\">enquiry@websitename.com</a></li>\r\n  <li>Address: [Company Address]</li>\r\n</ul>', '<h2>返金ポリシー</h2>\r\n<p>本返金・キャンセルポリシーでは、[Company Name]でのご購入について、どのような場合に返金が可能となるかを分かりやすくご説明します。当社の商品はデジタルです。お客様はクレジットを購入し、そのクレジットを使ってオンライン講座を解除します。</p>\r\n\r\n<h3>デジタル商品について</h3>\r\n<p>クレジットおよび講座はデジタルで提供され、即時にアクセスできるため、ご購入は原則として最終的なものとなります。ご購入前に内容を十分にご確認ください。</p>\r\n\r\n<h3>返金は購入したクレジットのみが対象です</h3>\r\n<p>返金が認められる場合、以下の点を明確にご確認ください。</p>\r\n<ul>\r\n  <li>返金の対象となるのは、<strong>購入したクレジットのみ</strong>（お客様がお支払いになったクレジット）です</li>\r\n  <li><strong>ボーナスクレジットはすべて返金対象外です。</strong>ボーナスクレジットは無料の特典であり、返金に含まれることはありません。チャージ時にボーナスクレジットが付与されていた場合、返金または取消の際に取り消されます</li>\r\n  <li>講座の解除にすでに<strong>使用された</strong>クレジットは返金対象外です</li>\r\n</ul>\r\n\r\n<h3>返金対象となる場合</h3>\r\n<p>以下の場合、購入したクレジットの返金対象となることがあります。</p>\r\n<ul>\r\n  <li>誤って請求された、または同一の購入に対して二重に請求された場合。または</li>\r\n  <li>当社側の実際の技術的問題によりクレジットが付与されず、当社が解決できない場合。かつ</li>\r\n  <li>返金を求めるクレジットが<strong>未使用</strong>であり、購入から相応の期間内にご請求いただいた場合</li>\r\n</ul>\r\n\r\n<h3>返金対象外となるもの</h3>\r\n<ul>\r\n  <li>あらゆる種類のボーナスクレジット</li>\r\n  <li>講座の解除にすでに使用されたクレジット</li>\r\n  <li>すでにアクセスまたは視聴された講座</li>\r\n  <li>相応の期間を過ぎてからご請求された購入</li>\r\n</ul>\r\n\r\n<h3>返金のご請求方法</h3>\r\n<p>返金をご希望の場合は、アカウントに登録されたアドレスから <a href=\"mailto:[Company Email]\">enquiry@websitename.com</a> までメールでご連絡いただき、注文番号とご請求の理由をお知らせください。購入内容の確認のため、追加情報をお伺いする場合があります。</p>\r\n\r\n<h3>処理について</h3>\r\n<p>ご請求が承認された場合、返金は元のお支払い方法に対して行われます。銀行やカード会社によっては、反映までに数営業日かかることがあります。返金額は<strong>購入したクレジットのみ</strong>を反映し、ボーナスクレジットは除外されます。</p>\r\n\r\n<h3>チャージバックについて</h3>\r\n<p>身に覚えのない請求がある場合は、銀行に異議を申し立てる前に当社までご連絡ください。多くの場合、より迅速に解決できます。なお、請求は当社の登録事業名（DBA）で明細書に表示されます。</p>\r\n\r\n<h3>お問い合わせ</h3>\r\n<ul>\r\n  <li><strong>[Company Name]</strong></li>\r\n  <li>メール：<a href=\"mailto:[Company Email]\">enquiry@websitename.com</a></li>\r\n  <li>住所：[Company Address]</li>\r\n</ul>', NULL, NULL),
(2, 'Privacy Policy', '個人情報保護方針', 'privacy-policy', '<h2>Privacy Policy</h2>\r\n<p>Welcome to [Company Name] (the &ldquo;Website&rdquo;, &ldquo;we&rdquo;, &ldquo;us&rdquo;, or &ldquo;our&rdquo;). We respect your privacy and are committed to protecting your personal information. This Privacy Policy explains, in plain language, what we collect when you use our online learning platform, why we collect it, and the choices you have.</p>\r\n\r\n<h3>Information We Collect</h3>\r\n<ul>\r\n  <li><strong>Account details</strong> &mdash; such as your name, email address, and password when you register</li>\r\n  <li><strong>Purchase information</strong> &mdash; the credits you buy and the courses you unlock. Card payments are handled by our payment providers; we do not store your full card number</li>\r\n  <li><strong>Billing details</strong> &mdash; such as your billing name, address, and country, used to process payments and prevent fraud</li>\r\n  <li><strong>Usage data</strong> &mdash; how you interact with the Website, such as pages viewed and courses watched, to improve our service</li>\r\n  <li><strong>Technical data</strong> &mdash; such as your device type, browser, and general location, collected through cookies and similar technologies</li>\r\n</ul>\r\n\r\n<h3>How We Use Your Information</h3>\r\n<ul>\r\n  <li>To create and manage your account and credit balance</li>\r\n  <li>To process your credit purchases and give you access to the courses you unlock</li>\r\n  <li>To provide customer support and respond to your enquiries</li>\r\n  <li>To keep the Website secure and prevent fraud or misuse</li>\r\n  <li>To improve our courses, categories, and overall experience</li>\r\n  <li>To send you important service messages, and &mdash; where you have agreed &mdash; occasional updates about new courses</li>\r\n</ul>\r\n\r\n<h3>Payment Processing</h3>\r\n<p>Credit purchases are processed by trusted third-party payment providers. Your payment is handled on their secure systems, and we receive only the information needed to confirm and manage your order.</p>\r\n\r\n<h3>Sharing Your Information</h3>\r\n<p>We do not sell your personal information. We share it only with:</p>\r\n<ul>\r\n  <li>payment providers, to process your purchases</li>\r\n  <li>service providers that help us run the Website (for example hosting and email)</li>\r\n  <li>authorities, where required by law</li>\r\n</ul>\r\n\r\n<h3>Cookies</h3>\r\n<p>We use cookies and similar technologies to keep you signed in, remember your preferences (such as language and currency), and understand how the Website is used. You can control cookies through your browser settings, though some features may not work without them.</p>\r\n\r\n<h3>Data Retention</h3>\r\n<p>We keep your information for as long as your account is active or as needed to provide our services, comply with legal obligations, resolve disputes, and enforce our agreements.</p>\r\n\r\n<h3>Security</h3>\r\n<p>We use reasonable technical and organisational measures to protect your information. However, no method of transmission over the internet is completely secure, so we cannot guarantee absolute security.</p>\r\n\r\n<h3>International Users</h3>\r\n<p>Our courses are offered to learners in Japan, Southeast Asia, and beyond. Your information may be processed in countries other than your own, and by using the Website you consent to this transfer.</p>\r\n\r\n<h3>Your Rights</h3>\r\n<p>Depending on your location, you may have the right to access, correct, or delete your personal information, or to object to certain uses. To make a request, contact us using the details below.</p>\r\n\r\n<h3>Children&rsquo;s Privacy</h3>\r\n<p>The Website is not intended for children below the age required to consent in their country. We do not knowingly collect information from such children.</p>\r\n\r\n<h3>Changes to This Policy</h3>\r\n<p>We may update this Privacy Policy from time to time. The latest version will always be available on this page.</p>\r\n\r\n<h3>Contact Us</h3>\r\n<p>If you have any questions about this Privacy Policy or your information, please contact us:</p>\r\n<ul>\r\n  <li><strong>[Company Name]</strong></li>\r\n  <li>Email: <a href=\"mailto:[Company Email]\">enquiry@websitename.com</a></li>\r\n  <li>Address: [Company Address]</li>\r\n</ul>', '<h2>個人情報保護方針</h2>\r\n<p>[Company Name]（以下「当ウェブサイト」「当社」）へようこそ。当社はお客様のプライバシーを尊重し、個人情報の保護に努めています。本個人情報保護方針では、当社のオンライン講座プラットフォームをご利用いただく際に取得する情報、その利用目的、およびお客様の選択肢について、分かりやすくご説明します。</p>\r\n\r\n<h3>取得する情報</h3>\r\n<ul>\r\n  <li><strong>アカウント情報</strong> ― 登録時のお名前、メールアドレス、パスワードなど</li>\r\n  <li><strong>購入情報</strong> ― 購入されたクレジットや解除された講座など。カード決済は決済事業者が処理し、カード番号の全体を当社が保存することはありません</li>\r\n  <li><strong>請求情報</strong> ― 請求先氏名、住所、国など。決済処理と不正防止に使用します</li>\r\n  <li><strong>利用データ</strong> ― 閲覧ページや視聴した講座など、当ウェブサイトの利用状況。サービス改善に使用します</li>\r\n  <li><strong>技術データ</strong> ― デバイスの種類、ブラウザ、おおよその地域など。クッキー等の技術を通じて取得します</li>\r\n</ul>\r\n\r\n<h3>情報の利用目的</h3>\r\n<ul>\r\n  <li>アカウントおよびクレジット残高の作成・管理のため</li>\r\n  <li>クレジット購入の処理、および解除された講座へのアクセス提供のため</li>\r\n  <li>カスタマーサポートの提供とお問い合わせへの対応のため</li>\r\n  <li>ウェブサイトの安全確保、不正利用の防止のため</li>\r\n  <li>講座、カテゴリー、全体的な体験の改善のため</li>\r\n  <li>重要なサービス連絡、およびご同意いただいた場合の新着講座のお知らせのため</li>\r\n</ul>\r\n\r\n<h3>決済処理</h3>\r\n<p>クレジットの購入は、信頼できる第三者の決済事業者により処理されます。お支払いは各社の安全なシステム上で行われ、当社は注文の確認・管理に必要な情報のみを受け取ります。</p>\r\n\r\n<h3>情報の共有</h3>\r\n<p>当社はお客様の個人情報を販売しません。以下の場合にのみ共有します。</p>\r\n<ul>\r\n  <li>購入処理のための決済事業者</li>\r\n  <li>ウェブサイト運営を支援するサービス提供者（ホスティングやメール送信など）</li>\r\n  <li>法律で求められる場合の当局</li>\r\n</ul>\r\n\r\n<h3>クッキー</h3>\r\n<p>当社は、ログイン状態の維持、設定（言語・通貨など）の記憶、利用状況の把握のために、クッキー等の技術を使用します。クッキーはブラウザ設定で管理できますが、一部の機能が利用できなくなる場合があります。</p>\r\n\r\n<h3>情報の保存期間</h3>\r\n<p>アカウントが有効な期間、またはサービス提供、法的義務の遵守、紛争解決、契約の履行に必要な期間、情報を保存します。</p>\r\n\r\n<h3>セキュリティ</h3>\r\n<p>当社は、情報保護のために合理的な技術的・組織的措置を講じています。ただし、インターネット上の通信は完全に安全とは言えないため、絶対的な安全性を保証することはできません。</p>\r\n\r\n<h3>海外の利用者について</h3>\r\n<p>当社の講座は、日本、東南アジア、およびその他の地域の学習者に提供されています。お客様の情報はお客様の居住国以外で処理される場合があり、当ウェブサイトのご利用をもって、この移転に同意いただいたものとみなします。</p>\r\n\r\n<h3>お客様の権利</h3>\r\n<p>お住まいの地域によっては、個人情報へのアクセス、訂正、削除を求める権利や、特定の利用に異議を唱える権利がある場合があります。ご請求は、下記の連絡先までお問い合わせください。</p>\r\n\r\n<h3>お子様のプライバシー</h3>\r\n<p>当ウェブサイトは、居住国で同意に必要な年齢に満たないお子様を対象としていません。当社は、そのようなお子様から意図的に情報を収集することはありません。</p>\r\n\r\n<h3>本方針の変更</h3>\r\n<p>当社は本方針を随時更新することがあります。最新版は常に本ページに掲載されます。</p>\r\n\r\n<h3>お問い合わせ</h3>\r\n<p>本方針またはお客様の情報に関するご質問は、以下までお問い合わせください。</p>\r\n<ul>\r\n  <li><strong>[Company Name]</strong></li>\r\n  <li>メール：<a href=\"mailto:[Company Email]\">enquiry@websitename.com</a></li>\r\n  <li>住所：[Company Address]</li>\r\n</ul>', NULL, NULL),
(3, 'Delivery Policy', '配送ポリシー', 'delivery-policy', '<h2>Delivery Policy</h2>\r\n<p>This Delivery Policy explains, simply and clearly, how you receive what you buy from [Company Name]. Everything we sell is <strong>digital</strong> &mdash; there is no physical shipping. You buy credits, and you use those credits to unlock online courses that you watch on our Website.</p>\r\n\r\n<h3>What You Receive</h3>\r\n<ul>\r\n  <li><strong>Credits</strong> &mdash; when you top up, credits are added to your account balance</li>\r\n  <li><strong>Course access</strong> &mdash; when you unlock a course with your credits, it is added to your personal dashboard for online viewing</li>\r\n</ul>\r\n\r\n<h3>How Credits Are Delivered</h3>\r\n<p>Once your payment is confirmed, your credits are normally added to your account <strong>instantly</strong>. You can see your balance at any time in your dashboard.</p>\r\n\r\n<h3>How Courses Are Delivered</h3>\r\n<p>After you spend credits to enrol in a course, access is granted <strong>immediately</strong>. The course appears in your dashboard, and you can start watching straight away, at your own pace, as often as you like while your access is active.</p>\r\n\r\n<h3>Delivery Time</h3>\r\n<p>Delivery of credits and course access is usually instant. During periods of high demand, or if a payment needs extra verification, it may take a little longer. If your credits or course have not appeared within a reasonable time, please contact us and we will help.</p>\r\n\r\n<h3>No Physical Delivery</h3>\r\n<p>Because our products are digital, we do not ship any physical items, and there are no shipping fees or delivery addresses to provide. All learning happens online through your account.</p>\r\n\r\n<h3>What You Need</h3>\r\n<ul>\r\n  <li>A registered account on the Website</li>\r\n  <li>A stable internet connection and an up-to-date browser</li>\r\n  <li>Enough credits in your balance to unlock the course you want</li>\r\n</ul>\r\n\r\n<h3>If Something Goes Wrong</h3>\r\n<p>If a payment is taken but your credits or course do not appear, please do not purchase again. Contact us with your order details and we will check and resolve it as quickly as possible.</p>\r\n\r\n<h3>Contact Us</h3>\r\n<ul>\r\n  <li><strong>[Company Name]</strong></li>\r\n  <li>Email: <a href=\"mailto:[Company Email]\">enquiry@websitename.com</a></li>\r\n  <li>Address: [Company Address]</li>\r\n</ul>', '<h2>配送ポリシー</h2>\r\n<p>本配送ポリシーでは、[Company Name]でご購入いただいた商品をどのようにお受け取りいただくかを、分かりやすくご説明します。当社が販売するものはすべて<strong>デジタル</strong>であり、物理的な配送はありません。お客様はクレジットを購入し、そのクレジットを使ってオンライン講座を解除し、当ウェブサイト上で視聴します。</p>\r\n\r\n<h3>お受け取りいただくもの</h3>\r\n<ul>\r\n  <li><strong>クレジット</strong> ― チャージすると、クレジットがアカウント残高に追加されます</li>\r\n  <li><strong>講座へのアクセス</strong> ― クレジットで講座を解除すると、オンライン視聴用にダッシュボードへ追加されます</li>\r\n</ul>\r\n\r\n<h3>クレジットの提供方法</h3>\r\n<p>お支払いが確認されると、通常クレジットは<strong>即時</strong>にアカウントへ追加されます。残高はいつでもダッシュボードで確認できます。</p>\r\n\r\n<h3>講座の提供方法</h3>\r\n<p>クレジットを使って講座に登録すると、アクセスは<strong>即時</strong>に付与されます。講座はダッシュボードに表示され、アクセスが有効な間は、ご自身のペースで何度でも視聴を開始できます。</p>\r\n\r\n<h3>提供までの時間</h3>\r\n<p>クレジットおよび講座アクセスの提供は通常即時です。アクセス集中時や、お支払いに追加確認が必要な場合は、少し時間がかかることがあります。相応の時間が経過してもクレジットや講座が表示されない場合は、当社までご連絡ください。</p>\r\n\r\n<h3>物理的な配送はありません</h3>\r\n<p>当社の商品はデジタルであるため、物理的な商品の発送はなく、送料や配送先住所のご入力も不要です。学習はすべて、アカウントを通じてオンラインで行われます。</p>\r\n\r\n<h3>ご利用に必要なもの</h3>\r\n<ul>\r\n  <li>当ウェブサイトの登録済みアカウント</li>\r\n  <li>安定したインターネット接続と最新のブラウザ</li>\r\n  <li>希望する講座を解除するのに十分なクレジット残高</li>\r\n</ul>\r\n\r\n<h3>問題が発生した場合</h3>\r\n<p>お支払いが完了したのにクレジットや講座が表示されない場合は、再度ご購入なさらないでください。ご注文内容を添えて当社までご連絡いただければ、できる限り速やかに確認・解決いたします。</p>\r\n\r\n<h3>お問い合わせ</h3>\r\n<ul>\r\n  <li><strong>[Company Name]</strong></li>\r\n  <li>メール：<a href=\"mailto:[Company Email]\">enquiry@websitename.com</a></li>\r\n  <li>住所：[Company Address]</li>\r\n</ul>', NULL, NULL),
(4, 'Terms & Conditions', 'ご利用規約', 'terms-conditions', '<h2>Terms &amp; Conditions</h2>\r\n\r\n<table style=\"width:100%;border-collapse:collapse;margin:0 0 28px;border:1px solid #dfdcd5;font-size:14px;\">\r\n  <tbody>\r\n    <tr><th style=\"text-align:left;padding:10px 14px;background:#e7e5e4;border:1px solid #dfdcd5;width:210px;\">Company Name</th><td style=\"padding:10px 14px;border:1px solid #dfdcd5;\">[Company Name]</td></tr>\r\n    <tr><th style=\"text-align:left;padding:10px 14px;background:#e7e5e4;border:1px solid #dfdcd5;\">Email</th><td style=\"padding:10px 14px;border:1px solid #dfdcd5;\"><a href=\"mailto:[Company Email]\">enquiry@websitename.com</a></td></tr>\r\n    <tr><th style=\"text-align:left;padding:10px 14px;background:#e7e5e4;border:1px solid #dfdcd5;\">Address</th><td style=\"padding:10px 14px;border:1px solid #dfdcd5;\">[Company Address]</td></tr>\r\n    <tr><th style=\"text-align:left;padding:10px 14px;background:#e7e5e4;border:1px solid #dfdcd5;\">DBA (Doing Business As)</th><td style=\"padding:10px 14px;border:1px solid #dfdcd5;\"><img src=\"/assets/images/dba.webp\" alt=\"DBA\" class=\"dba-inline\"></td></tr>\r\n  </tbody>\r\n</table>\r\n\r\n<p>Welcome to [Company Name] (&ldquo;we&rdquo;, &ldquo;us&rdquo;, &ldquo;our&rdquo;, or the &ldquo;Website&rdquo;). We are an online learning platform where you can learn practical skills through structured, self-paced video courses. These Terms &amp; Conditions (the &ldquo;Terms&rdquo;) form the agreement between you and [Company Name] whenever you visit the Website, create an account, buy credits, or enrol in a course.</p>\r\n<p>Please read these Terms carefully. By using the Website, creating an account, or making a purchase, you confirm that you have read, understood, and agreed to them. If you do not agree, please do not use the Website.</p>\r\n\r\n<h3>Who We Are</h3>\r\n<p>[Company Name] provides pre-recorded online courses across a range of practical topics. Our courses are grouped into categories such as <strong>Talk &amp; Connect</strong>, <strong>Career Boost</strong>, <strong>Tech Up</strong>, <strong>Creative Hub</strong>, and <strong>Life Skills</strong>. Each course is created for learners at different stages, from complete beginners to experts.</p>\r\n\r\n<h3>Eligibility &amp; Your Account</h3>\r\n<ul>\r\n  <li>You must be able to form a legally binding contract to use the Website. If you are under the age required in your country, please use the Website only with the involvement of a parent or guardian</li>\r\n  <li>You are responsible for the information you provide and for keeping your login details private</li>\r\n  <li>You are responsible for all activity that happens under your account. Please tell us straight away if you think someone else has used it</li>\r\n</ul>\r\n\r\n<h3>How It Works &mdash; Credits First, Then Courses</h3>\r\n<p>Our platform uses a simple two-step model:</p>\r\n<ul>\r\n  <li><strong>Step 1 &mdash; Buy credits.</strong> You first top up your account with <em>credits</em> using a supported payment method and currency (for example JPY(¥), HKD (HK$), or USD ($)). The number of credits you receive is based on the amount you pay at the exchange rate shown at checkout</li>\r\n  <li><strong>Step 2 &mdash; Enrol using credits.</strong> You then spend those credits to unlock the course and skill level you want. Once unlocked, the course is added to your personal dashboard so you can watch it whenever you like</li>\r\n</ul>\r\n<p>Many courses offer several skill levels (for example <strong>Beginner</strong>, <strong>Intermediate</strong>, <strong>Advanced</strong>, and <strong>Expert</strong>), and each level has its own price in credits.</p>\r\n\r\n<h3>Credits</h3>\r\n<ul>\r\n  <li>Credits are a prepaid balance that can be used <strong>only</strong> to unlock courses on the Website. They have no cash value and cannot be exchanged, withdrawn, or redeemed for money</li>\r\n  <li>Some top-up tiers include <strong>bonus credits</strong> as a promotional extra. Bonus credits are a free benefit and, as explained in our <a href=\"/refund-policy\">Refund Policy</a>, are <strong>non-refundable</strong></li>\r\n  <li>Credits are linked to your account and are non-transferable between accounts</li>\r\n  <li>We may update credit pricing, tiers, or bonus offers from time to time. Any change applies to future purchases only</li>\r\n</ul>\r\n\r\n<h3>Payments &amp; Billing</h3>\r\n<p>Payments are processed securely by trusted third-party payment providers. We do not store your full card details on our servers. By paying, you confirm that you are authorised to use the chosen payment method and that the information you provide is accurate.</p>\r\n<p><strong>Note:</strong> Charges for purchases on this website will appear as <img src=\"/assets/images/dba.webp\" alt=\"DBA\" class=\"dba-inline\"> on your credit card or bank statement. If you do not recognise a charge, please contact us before disputing it with your bank so we can help.</p>\r\n\r\n<h3>Course Access &amp; Licence</h3>\r\n<p>When you unlock a course with your credits, we grant you a personal, non-exclusive, non-transferable licence to view that course for your own learning. You may not share, resell, sublicense, broadcast, or publicly distribute any course, nor download and redistribute the videos or materials.</p>\r\n\r\n<h3>Intellectual Property</h3>\r\n<p>All content on the Website &mdash; including course videos, artwork, lesson materials, text, graphics, logos, and the Website design &mdash; belongs to [Company Name] or its licensors and instructors, and is protected by copyright and other laws. Nothing on the Website transfers ownership of that content to you.</p>\r\n\r\n<h3>Acceptable Use</h3>\r\n<p>When using the Website, you agree not to:</p>\r\n<ul>\r\n  <li>copy, record, download, or redistribute course content except where a download is expressly provided</li>\r\n  <li>share your account or course access with anyone else</li>\r\n  <li>attempt to disrupt, hack, or gain unauthorised access to the Website or other users&rsquo; accounts</li>\r\n  <li>use the Website for any unlawful purpose or in breach of these Terms</li>\r\n</ul>\r\n\r\n<h3>Learning Outcomes</h3>\r\n<p>Our courses are designed to help you build real skills, but everyone learns differently. We do not guarantee specific results, income, employment, or learning outcomes, as these depend on your own effort and practice.</p>\r\n\r\n<h3>Refunds</h3>\r\n<p>Purchases of credits and courses are digital. Refunds, where available, are handled in line with our <a href=\"/refund-policy\">Refund Policy</a>. Please note in particular that any eligible refund covers <strong>purchased credits only</strong>, and that <strong>bonus credits are non-refundable</strong>.</p>\r\n\r\n<h3>Limitation of Liability</h3>\r\n<p>The Website and its content are provided on an &ldquo;as is&rdquo; basis. To the fullest extent permitted by law, [Company Name] will not be liable for any indirect or consequential loss arising from your use of the Website. Nothing in these Terms limits any rights you have that cannot be excluded under applicable law.</p>\r\n\r\n<h3>Suspension &amp; Termination</h3>\r\n<p>We may suspend or close accounts that breach these Terms, misuse credits, or attempt to redistribute course content. If we close your account for a serious breach, you may lose access to credits and courses without refund.</p>\r\n\r\n<h3>Changes to These Terms</h3>\r\n<p>We may update these Terms from time to time. The latest version will always be posted on this page, and your continued use of the Website means you accept the updated Terms.</p>\r\n\r\n<h3>Governing Law</h3>\r\n<p>These Terms and Conditions shall be governed by the laws of Hong Kong.</p>\r\n\r\n<h3>Contact Us</h3>\r\n<p>If you have any questions about these Terms, please contact us:</p>\r\n<ul>\r\n  <li><strong>[Company Name]</strong></li>\r\n  <li>Email: <a href=\"mailto:[Company Email]\">enquiry@websitename.com</a></li>\r\n  <li>Address: [Company Address]</li>\r\n</ul>', '<h2>ご利用規約</h2>\r\n\r\n<table style=\"width:100%;border-collapse:collapse;margin:0 0 28px;border:1px solid #dfdcd5;font-size:14px;\">\r\n  <tbody>\r\n    <tr><th style=\"text-align:left;padding:10px 14px;background:#e7e5e4;border:1px solid #dfdcd5;width:210px;\">会社名</th><td style=\"padding:10px 14px;border:1px solid #dfdcd5;\">[Company Name]</td></tr>\r\n    <tr><th style=\"text-align:left;padding:10px 14px;background:#e7e5e4;border:1px solid #dfdcd5;\">メール</th><td style=\"padding:10px 14px;border:1px solid #dfdcd5;\"><a href=\"mailto:[Company Email]\">enquiry@websitename.com</a></td></tr>\r\n    <tr><th style=\"text-align:left;padding:10px 14px;background:#e7e5e4;border:1px solid #dfdcd5;\">住所</th><td style=\"padding:10px 14px;border:1px solid #dfdcd5;\">[Company Address]</td></tr>\r\n    <tr><th style=\"text-align:left;padding:10px 14px;background:#e7e5e4;border:1px solid #dfdcd5;\">DBA（屋号）</th><td style=\"padding:10px 14px;border:1px solid #dfdcd5;\"><img src=\"/assets/images/dba.webp\" alt=\"DBA\" class=\"dba-inline\"></td></tr>\r\n  </tbody>\r\n</table>\r\n\r\n<p>[Company Name]（以下「当社」「当ウェブサイト」）へようこそ。当社は、体系的に構成された自分のペースで学べる動画講座を通じて、実践的なスキルを学べるオンライン学習プラットフォームです。本ご利用規約（以下「本規約」）は、お客様が当ウェブサイトを利用し、アカウントを作成し、クレジットを購入し、または講座に登録される際の、お客様と[Company Name]との間の合意を定めるものです。</p>\r\n<p>本規約をよくお読みください。当ウェブサイトのご利用、アカウントの作成、またはご購入をもって、本規約に同意いただいたものとみなします。ご同意いただけない場合は、当ウェブサイトをご利用にならないでください。</p>\r\n\r\n<h3>当社について</h3>\r\n<p>[Company Name]は、さまざまな創作スタイルの録画済みオンライン講座を提供しています。講座は、<strong>トーク＆コネクト</strong>、<strong>キャリアブースト</strong>、<strong>テックアップ</strong>、<strong>クリエイティブハブ</strong>、<strong>ライフスキル</strong>などのカテゴリーに分類されています。各講座は、初心者から上級者まで、さまざまな段階の学習者向けに作られています。</p>\r\n\r\n<h3>利用資格とアカウント</h3>\r\n<ul>\r\n  <li>当ウェブサイトを利用するには、法的に有効な契約を締結できる必要があります。お住まいの国で必要な年齢に達していない場合は、保護者の関与のもとでのみご利用ください</li>\r\n  <li>ご提供いただく情報、およびログイン情報の管理はお客様の責任となります</li>\r\n  <li>お客様のアカウントで行われるすべての活動について、お客様が責任を負います。第三者による不正利用が疑われる場合は、直ちに当社までご連絡ください</li>\r\n</ul>\r\n\r\n<h3>ご利用の流れ ― まずクレジット、次に講座</h3>\r\n<p>当プラットフォームはシンプルな2ステップ制です。</p>\r\n<ul>\r\n  <li><strong>ステップ1 ― クレジットを購入。</strong>まず、対応する決済方法と通貨（例：JPY(¥)、HKD(HK$)、USD($)）を使ってアカウントに<em>クレジット</em>をチャージします。付与されるクレジット数は、チェックアウト時に表示される為替レートに基づき、お支払い金額に応じて計算されます</li>\r\n  <li><strong>ステップ2 ― クレジットで登録。</strong>そのクレジットを使って、希望する講座とレベルを解除します。解除された講座はダッシュボードに追加され、いつでも視聴できます</li>\r\n</ul>\r\n<p>多くの講座には複数のレベル（例：<strong>ビギナー</strong>、<strong>中級</strong>、<strong>アドバンスド</strong>、<strong>専門家</strong>）があり、各レベルにはクレジット単位の価格が設定されています。</p>\r\n\r\n<h3>クレジットについて</h3>\r\n<ul>\r\n  <li>クレジットは前払い残高であり、当ウェブサイトの講座を解除するためだけに使用できます。現金価値はなく、現金への交換・払い戻し・換金はできません</li>\r\n  <li>一部のチャージ区分には、特典として<strong>ボーナスクレジット</strong>が含まれます。ボーナスクレジットは無料の特典であり、<a href=\"/refund-policy\">返金ポリシー</a>に記載のとおり<strong>返金対象外</strong>です</li>\r\n  <li>クレジットはお客様のアカウントに紐づき、他のアカウントへ譲渡することはできません</li>\r\n  <li>クレジットの価格、区分、ボーナス内容は随時変更される場合があります。変更は今後の購入にのみ適用されます</li>\r\n</ul>\r\n\r\n<h3>お支払いと請求</h3>\r\n<p>お支払いは、信頼できる第三者の決済事業者により安全に処理されます。当社のサーバーにカード情報の全体を保存することはありません。お支払いをもって、選択された決済方法を利用する権限があること、および提供する情報が正確であることを確認したものとみなします。</p>\r\n<p><strong>ご注意：</strong>当ウェブサイトでのご購入に対する請求は、クレジットカードまたは銀行の明細書に <img src=\"/assets/images/dba.webp\" alt=\"DBA\" class=\"dba-inline\"> として表示されます。身に覚えのない請求がある場合は、銀行に異議を申し立てる前に当社までご連絡ください。</p>\r\n\r\n<h3>講座へのアクセスとライセンス</h3>\r\n<p>クレジットで講座を解除すると、当社はお客様に対し、ご自身の学習のためにその講座を視聴する、個人的・非独占的・譲渡不可のライセンスを付与します。講座の共有、再販売、再許諾、放送、公衆への配布、または動画・教材のダウンロードや再配布はできません。</p>\r\n\r\n<h3>知的財産</h3>\r\n<p>講座動画、アートワーク、教材、テキスト、画像、ロゴ、ウェブサイトのデザインを含む当ウェブサイト上のすべてのコンテンツは、[Company Name]またはそのライセンサーおよび講師に帰属し、著作権その他の法律により保護されています。当ウェブサイトの利用によって、これらのコンテンツの所有権がお客様に移転することはありません。</p>\r\n\r\n<h3>禁止事項</h3>\r\n<p>当ウェブサイトの利用にあたり、以下の行為を行わないことに同意するものとします。</p>\r\n<ul>\r\n  <li>ダウンロードが明示的に提供されている場合を除き、講座コンテンツの複製、録画、ダウンロード、再配布を行うこと</li>\r\n  <li>アカウントや講座へのアクセスを他者と共有すること</li>\r\n  <li>当ウェブサイトや他の利用者のアカウントを妨害・ハッキング・不正アクセスしようとすること</li>\r\n  <li>違法な目的、または本規約に違反する方法で当ウェブサイトを利用すること</li>\r\n</ul>\r\n\r\n<h3>学習成果について</h3>\r\n<p>当社の講座は実践的なスキルの習得を支援するよう設計されていますが、学び方は人それぞれです。成果、収入、就職、または学習結果は、お客様ご自身の努力と練習によって左右されるため、特定の結果を保証するものではありません。</p>\r\n\r\n<h3>返金について</h3>\r\n<p>クレジットおよび講座のご購入はデジタル商品です。返金は、対応可能な場合、<a href=\"/refund-policy\">返金ポリシー</a>に従って処理されます。特に、返金対象となる場合でも<strong>購入したクレジットのみ</strong>が対象であり、<strong>ボーナスクレジットは返金対象外</strong>である点にご留意ください。</p>\r\n\r\n<h3>責任の制限</h3>\r\n<p>当ウェブサイトおよびそのコンテンツは「現状のまま」提供されます。法律で認められる最大限の範囲において、[Company Name]は当ウェブサイトの利用から生じる間接的・結果的損害について責任を負いません。本規約は、適用法により排除できないお客様の権利を制限するものではありません。</p>\r\n\r\n<h3>利用停止と解約</h3>\r\n<p>本規約に違反した場合、クレジットを不正利用した場合、または講座コンテンツを再配布しようとした場合、当社はアカウントを停止または閉鎖することがあります。重大な違反によりアカウントを閉鎖した場合、クレジットや講座へのアクセスが返金なく失われることがあります。</p>\r\n\r\n<h3>本規約の変更</h3>\r\n<p>当社は本規約を随時更新することがあります。最新版は常に本ページに掲載され、当ウェブサイトを継続してご利用いただくことで、更新後の規約に同意いただいたものとみなします。</p>\r\n\r\n<h3>準拠法</h3>\r\n<p>これらの利用規約は、香港の法律に準拠するものとします。</p>\r\n\r\n<h3>お問い合わせ</h3>\r\n<p>本規約に関するご質問は、以下までお問い合わせください。</p>\r\n<ul>\r\n  <li><strong>[Company Name]</strong></li>\r\n  <li>メール：<a href=\"mailto:[Company Email]\">enquiry@websitename.com</a></li>\r\n  <li>住所：[Company Address]</li>\r\n</ul>', NULL, NULL),
(5, 'About Us', '私達について', 'about-us', '<section class=\"about-section\">\n		<div class=\"container\">\n			<div class=\"section-wrapper padding-top\">\n				<div class=\"row\">\n					<div class=\"col-lg-6\">\n						<div class=\"about-image\">\n							<img src=\"assets/images/about/about-1.jpg\" alt=\"about-image\">\n						</div>\n					</div>\n					<div class=\"col-lg-6 col-md-10\">\n						<div class=\"about-wrapper\">\n							<div class=\"section-header\">\n								<p>who we are</p>\n								<h2> WE ARE A PRO TEAM FOR GAME BOOSTING</h2>\n							</div>\n							<div class=\"about-content\">\n								<p> Expert players help clients climb faster with secure, fast, and transparent services — no cheats, just pure skill and dedication.\n</p>\n								<ul class=\"about-list\">\n									<li class=\"about-item d-flex flex-wrap\">\n										<div class=\"about-item-thumb\">\n											<img src=\"assets/images/about/icon-1.png\" alt=\"Icon\">\n										</div>\n										<div class=\"about-item-content\">\n											<h5>SKILLED BOOSTERS</h5>\n											<p>Helping gamers level up with precision and strategy across the most competitive titles.</p>\n										</div></li>\n									<li class=\"about-item d-flex flex-wrap\">\n										<div class=\"about-item-thumb\">\n											<img src=\"assets/images/about/icon-2.png\" alt=\"Icon\">\n										</div>\n										<div class=\"about-item-content\">\n											<h5>TRUSTED APPROACH</h5>\n											<p>Players rely on us for consistent, confidential, and high-quality service every time.</p>\n										</div></li>\n									<li class=\"about-item d-flex flex-wrap\">\n										<div class=\"about-item-thumb\">\n											<img src=\"assets/images/about/icon-3.png\" alt=\"Icon\">\n										</div>\n										<div class=\"about-item-content\">\n											<h5>DEDICATED HOURS</h5>\n											<p> Delivered through focused gameplay, optimized routes, and smart in-game decision-making.</p>\n										</div></li>\n								</ul>\n							</d